import{j as u,a as me}from"./vendor-react-DzFdt34V.js";import{f as Z,v as X,r as k,p as x,M as oe,u as ue,O as Ee,F as $e,J as Ce,H as Pe,I as Ie,m as O,w as V,s as ee,o as re,B as Te,d as Ze,e as He,i as De,U as Se}from"./LabKit-B0mLIUGG.js";import{r as be,C as Me,U as Be,T as We,a as Le,S as Ue,R as Re}from"./ProportionTools-CXxm3jLC.js";import{M as Ne,R as Fe,P as Ke,D as Oe,U as Ge,a as Qe,I as Ye,b as _e,c as Ve,d as Je,e as Xe,W as ea,f as aa,g as ta,C as oa,h as ra}from"./figures-nbD0yzA7.js";import{P as na}from"./PairsMemoryGame-SzCLOQjW.js";/* empty css              */import{D as ia}from"./DetectiveArt-CrOZ70O3.js";import{R as ke,a as ge}from"./RoundGame-C7XnAOUj.js";import{s as fe}from"./equations-CPmlT-KJ.js";/* empty css                  */import{c as sa,W as da}from"./WorkedDetectiveGame-CYMbavB_.js";/* empty css            */import{P as ca}from"./ProportionTool-Be9dbTOg.js";import{p as Q,a as ua,P as la,b as $a,c as pa}from"./labTools-CB0mmyFr.js";import"./index-D6Eglg0q.js";import"./vendor-i18n-D_kkcOKx.js";import"./vendor-CAIZfmPq.js";import"./vendor-katex-CdCLdKXh.js";import"./plane-CiFHPiQm.js";import"./answers-DcZ3f_sr.js";import"./figures-BktNieLD.js";/* empty css              */import"./polynomials-BHpm96H0.js";/* empty css                  */import"./extraChallenges-I9sMvRpb.js";import"./types-D0REvJHO.js";import"./PredictionStep-Dm1jIMJh.js";import"./notation-BaZ3uylG.js";const n=(e,i,a,t)=>({eu:e,es:i,en:t,ar:a.replace(/\{,\}/g,".")}),c=e=>({eu:e,es:e,en:e,ar:e.replace(/\{,\}/g,".")}),T=e=>{const[i,a=""]=e.split(",");return Z(Number(i+a),10**a.length)},h=e=>Z(e),ha=[{id:1201,prompt:n("Zein ez da magnitudea?","¿Cuál no es una magnitud?","أيها ليس مقدارًا؟","Which is not a quantity?"),options:[n("Edertasuna","La belleza","الجمال","Beauty"),n("Patata-zaku baten pisua","El peso de un saco de patatas","وزن كيس بطاطا","The weight of a sack of potatoes"),n("Bizikleta baten prezioa","El precio de una bici","ثمن دراجة","The price of a bike")],correctIndex:0,explanation:n("Edertasuna ezin da zenbaki eta unitate batekin neurtu. Pisua (kg) eta prezioa (€) bai.","La belleza no se puede medir con un número y una unidad. El peso (kg) y el precio (€), sí.","لا يمكن قياس الجمال بعدد ووحدة. أما الوزن (كغ) والسعر (€) فنعم.","Beauty cannot be measured with a number and a unit. Weight (kg) and price (€) can."),topic:"magnitude"},{id:1202,prompt:n("Zein da 6 kg pentsuren eta 10 behiren arteko arrazoiaren balioa?","¿Cuánto vale la razón entre 6 kg de pienso y 10 vacas?","كم قيمة النسبة بين 6 كغ من العلف و10 أبقار؟","What is the ratio between 6 kg of feed and 10 cows?"),options:[c("$1{,}6$"),c("$0{,}6$"),c("$4$")],correctIndex:1,explanation:c("$\\frac{6}{10}=6\\mathbin{:}10=0{,}6$"),topic:"ratio"},{id:1203,prompt:n("Aurkitu $x$: $\\frac{3}{6}=\\frac{7}{x}$.","Halla $x$: $\\frac{3}{6}=\\frac{7}{x}$.","أوجد $x$: $\\frac{3}{6}=\\frac{7}{x}$.","Find $x$: $\\frac{3}{6}=\\frac{7}{x}$."),options:[c("$21$"),c("$3{,}5$"),c("$14$")],correctIndex:2,explanation:n("$3\\cdot x=6\\cdot 7=42$, beraz $x=42\\mathbin{:}3=14$.","$3\\cdot x=6\\cdot 7=42$, así que $x=42\\mathbin{:}3=14$.","$3\\cdot x=6\\cdot 7=42$، إذن $x=42\\mathbin{:}3=14$.","$3\\cdot x=6\\cdot 7=42$, so $x=42\\mathbin{:}3=14$."),topic:"proportion"},{id:1204,prompt:n("Zein bikote da zuzenki proportzionala?","¿Qué pareja es directamente proporcional?","أي زوج متناسب طرديًا؟","Which pair is directly proportional?"),options:[n("Adina eta altuera","La edad y la altura","العمر والطول","Age and height"),n("Laranja-kiloak eta haien prezioa","Los kilos de naranjas y su precio","كيلوغرامات البرتقال وثمنها","The kilos of oranges and their price"),n("Abiadura eta denbora","La velocidad y el tiempo","السرعة والزمن","Speed and time")],correctIndex:1,explanation:n("Kilo bikoitzak prezio bikoitza. Adina eta altuera ez dira proportzionalak, eta abiadura eta denbora alderantziz proportzionalak dira.","El doble de kilos, el doble de precio. La edad y la altura no son proporcionales, y la velocidad y el tiempo son inversamente proporcionales.","ضعف الكيلوغرامات ضعف الثمن. أما العمر والطول فليسا متناسبين، والسرعة والزمن متناسبان عكسيًا.","Twice the kilos, twice the price. Age and height are not proportional, and speed and time are inversely proportional."),topic:"direct"},{id:1205,prompt:n("Kanguru batek 12 m egiten ditu 4 jauzitan. Zenbat 10 jauzitan?","Un canguro avanza 12 m en 4 saltos. ¿Cuánto en 10 saltos?","يقطع كنغر 12 م في 4 قفزات. كم يقطع في 10 قفزات؟","A kangaroo moves 12 m in 4 jumps. How far does it go in 10 jumps?"),options:[c("30 m"),c("18 m"),c("120 m")],correctIndex:0,explanation:c("$12\\mathbin{:}4=3\\ \\to\\ 3\\cdot 10=30$"),topic:"direct-unit"},{id:1206,prompt:n("Bi margolarik horma bat 9 ordutan margotzen dute. Zenbat ordu behar dituzte hiruk?","Dos pintores pintan una pared en 9 horas. ¿Cuántas horas tardan tres?","يدهن رسّامان جدارًا في 9 ساعات. كم ساعة يحتاج ثلاثة؟","Two painters paint a wall in 9 hours. How many hours would three painters take?"),options:[c("13,5 h"),c("6 h"),c("4,5 h")],correctIndex:1,explanation:n("Alderantzizkoa da: $9\\cdot 2=18$ ordu batek, $18\\mathbin{:}3=6$ ordu hiruk.","Es inversa: $9\\cdot 2=18$ horas uno solo, $18\\mathbin{:}3=6$ horas tres.","إنه عكسي: $9\\cdot 2=18$ ساعة للواحد، و$18\\mathbin{:}3=6$ ساعات للثلاثة.","It is inverse: $9\\cdot 2=18$ hours for one painter, $18\\mathbin{:}3=6$ hours for three."),topic:"inverse-unit"},{id:1207,prompt:n("Zenbat da 80ren % 25?","¿Cuánto es el 25 % de 80?","كم يساوي 25٪ من 80؟","What is 25% of 80?"),options:[c("20"),c("25"),c("55")],correctIndex:0,explanation:n("% 25 laurdena da: $80\\mathbin{:}4=20$.","El 25 % es la cuarta parte: $80\\mathbin{:}4=20$.","25٪ هي الربع: $80\\mathbin{:}4=20$.","25% is a quarter: $80\\mathbin{:}4=20$."),topic:"percent-of"},{id:1208,prompt:n("Beroki batek 80 € balio du eta % 10 merkatu dute. Zenbat ordainduko dut?","Un abrigo cuesta 80 € y lo rebajan un 10 %. ¿Cuánto pagaré?","ثمن معطف 80 € وخُفّض 10٪. كم سأدفع؟","A coat costs €80 and is reduced by 10%. How much will I pay?"),options:[c("70 €"),c("8 €"),c("72 €")],correctIndex:2,explanation:n("Beherapena $80\\cdot 10\\mathbin{:}100=8$ € da; ordaintzen dena, $80-8=72$ €. Ez da 10 € kentzea.","El descuento es $80\\cdot 10\\mathbin{:}100=8$ €; se paga $80-8=72$ €. No es quitar 10 €.","الخصم $80\\cdot 10\\mathbin{:}100=8$ €؛ والمدفوع $80-8=72$ €. ليس طرح 10 €.","The discount is $80\\cdot 10\\mathbin{:}100=8$ €; you pay $80-8=72$ €. It is not the same as taking €10 off."),topic:"discount"}],ma=[{id:1,stage:"ratios",prompt:n("Hiru kilo sagarrek 15 € balio dute. Zein da euroen eta kiloen arteko arrazoiaren balioa?","Tres kilos de manzanas cuestan 15 €. ¿Cuánto vale la razón entre euros y kilos?","ثمن ثلاثة كيلوغرامات من التفاح 15 €. كم قيمة النسبة بين اليورو والكيلوغرامات؟","Three kilos of apples cost €15. What is the ratio of euros to kilos?"),expected:h(5),hint:n("Aurrekaria euroak, ondorengoa kiloak.","Antecedente, los euros; consecuente, los kilos.","المقدَّم اليورو والتالي الكيلوغرامات.","Antecedent: the euros; consequent: the kilos."),explanation:c("$\\frac{15}{3}=15\\mathbin{:}3=5$")},{id:2,stage:"ratios",prompt:n("Aurkitu $x$: $\\frac{2}{7}=\\frac{x}{21}$.","Halla $x$: $\\frac{2}{7}=\\frac{x}{21}$.","أوجد $x$: $\\frac{2}{7}=\\frac{x}{21}$.","Find $x$: $\\frac{2}{7}=\\frac{x}{21}$."),expected:h(6),hint:n("$7\\cdot x=2\\cdot 21$.","$7\\cdot x=2\\cdot 21$.","$7\\cdot x=2\\cdot 21$.","$7\\cdot x=2\\cdot 21$."),explanation:c("$7\\cdot x=2\\cdot 21=42\\ \\to\\ x=42\\mathbin{:}7=6$")},{id:3,stage:"ratios",prompt:n("Aurkitu $x$: $\\frac{1{,}2}{0{,}6}=\\frac{x}{1{,}5}$.","Halla $x$: $\\frac{1{,}2}{0{,}6}=\\frac{x}{1{,}5}$.","أوجد $x$: $\\frac{1{,}2}{0{,}6}=\\frac{x}{1{,}5}$.","Find $x$: $\\frac{1{,}2}{0{,}6}=\\frac{x}{1{,}5}$."),expected:h(3),hint:n("Arrazoiak decimalak izan daitezke: gurutzeko biderkadurak berdin.","Las razones pueden tener decimales: los productos cruzados, igual.","قد تكون في النسب أعداد عشرية: والضرب التبادلي كما هو.","Ratios can have decimals: cross-multiplying works in the same way."),explanation:c("$0{,}6\\cdot x=1{,}2\\cdot 1{,}5=1{,}8\\ \\to\\ x=1{,}8\\mathbin{:}0{,}6=3$")},{id:4,stage:"ratios",prompt:n("Osatu arrazoi berdinen seriea: $\\frac{3}{15}=\\frac{5}{x}$.","Completa la serie de razones iguales: $\\frac{3}{15}=\\frac{5}{x}$.","أكمل سلسلة النسب المتساوية: $\\frac{3}{15}=\\frac{5}{x}$.","Complete the series of equal ratios: $\\frac{3}{15}=\\frac{5}{x}$."),expected:h(25),hint:n("Konstantea: $3\\mathbin{:}15=0{,}2$.","La constante: $3\\mathbin{:}15=0{,}2$.","الثابت: $3\\mathbin{:}15=0{,}2$.","The constant: $3\\mathbin{:}15=0{,}2$."),explanation:c("$3\\cdot x=15\\cdot 5=75\\ \\to\\ x=75\\mathbin{:}3=25$")},{id:5,stage:"direct",prompt:n("3 errotulagailuk 6 € balio dute. Zenbat balio dute 9k?","3 rotuladores cuestan 6 €. ¿Cuánto cuestan 9?","ثمن 3 أقلام تلوين 6 €. كم ثمن 9؟","3 felt-tip pens cost €6. How much do 9 cost?"),expected:h(18),hint:n("Errotulagailu batek: $6\\mathbin{:}3$.","Un rotulador: $6\\mathbin{:}3$.","القلم الواحد: $6\\mathbin{:}3$.","One felt-tip pen: $6\\mathbin{:}3$."),explanation:c("$6\\mathbin{:}3=2\\ \\to\\ 2\\cdot 9=18$")},{id:6,stage:"direct",prompt:n("Bi kilo laranjak $1{,}50$ € balio dute. Zenbat balio dute 12 kilok?","Dos kilos de naranjas cuestan $1{,}50$ €. ¿Cuánto cuestan 12 kilos?","ثمن كيلوغرامين من البرتقال $1{,}50$ €. كم ثمن 12 كيلوغرامًا؟","Two kilos of oranges cost €$1{,}50$. How much do 12 kilos cost?"),expected:h(9),hint:n("Kilo batek: $1{,}50\\mathbin{:}2$.","Un kilo: $1{,}50\\mathbin{:}2$.","الكيلو الواحد: $1{,}50\\mathbin{:}2$.","One kilo: $1{,}50\\mathbin{:}2$."),explanation:c("$1{,}50\\mathbin{:}2=0{,}75\\ \\to\\ 0{,}75\\cdot 12=9$")},{id:7,stage:"direct",prompt:n("100 g izokin ketuak $2{,}40$ € balio dute. Zenbat balio dute 260 g-k?","100 g de salmón ahumado cuestan $2{,}40$ €. ¿Cuánto cuestan 260 g?","ثمن 100 غ من السلمون المدخّن $2{,}40$ €. كم ثمن 260 غ؟","100 g of smoked salmon cost €$2{,}40$. How much do 260 g cost?"),expected:T("6,24"),hint:n("Hiruko erregela: $\\frac{100}{2{,}40}=\\frac{260}{x}$.","Regla de tres: $\\frac{100}{2{,}40}=\\frac{260}{x}$.","قاعدة الثلاثة: $\\frac{100}{2{,}40}=\\frac{260}{x}$.","Rule of three: $\\frac{100}{2{,}40}=\\frac{260}{x}$."),explanation:c("$x=\\frac{260\\cdot 2{,}40}{100}=6{,}24$")},{id:8,stage:"direct",prompt:n("Sagar-kilo batek $1{,}50$ € balio du. Zenbat balio dute 7 kilok?","Un kilo de manzanas cuesta $1{,}50$ €. ¿Cuánto cuestan 7 kilos?","ثمن كيلو التفاح $1{,}50$ €. كم ثمن 7 كيلوغرامات؟","One kilo of apples costs €$1{,}50$. How much do 7 kilos cost?"),expected:T("10,5"),hint:n("Konstantea $1{,}50$ da: biderkatu.","La constante es $1{,}50$: multiplica.","الثابت $1{,}50$: اضرب.","The constant is $1{,}50$: multiply."),explanation:c("$1{,}50\\cdot 7=10{,}5$")},{id:9,stage:"inverse",prompt:n("4 langilek eraikin bat 5 ordutan garbitzen dute. Zenbat ordu beharko lituzkete 10 langilek?","4 operarios limpian un edificio en 5 horas. ¿Cuántas horas tardarían 10 operarios?","ينظّف 4 عمال مبنى في 5 ساعات. كم ساعة يحتاج 10 عمال؟","4 workers clean a building in 5 hours. How many hours would 10 workers take?"),expected:h(2),hint:n("Langile bakarrak: $5\\cdot 4$ ordu.","Un solo operario: $5\\cdot 4$ horas.","العامل الواحد: $5\\cdot 4$ ساعات.","One worker alone: $5\\cdot 4$ hours."),explanation:c("$5\\cdot 4=20\\ \\to\\ 20\\mathbin{:}10=2$")},{id:10,stage:"inverse",prompt:n("3 igeltserok horma bat 8 ordutan zarpiatzen dute. Zenbat beharko luke igeltsero bakar batek?","3 albañiles enfoscan una pared en 8 horas. ¿Cuánto tardaría un solo albañil?","يليّس 3 بنّائين جدارًا في 8 ساعات. كم يحتاج بنّاء واحد؟","3 bricklayers plaster a wall in 8 hours. How long would one bricklayer take?"),expected:h(24),hint:n("Bakarrak denbora gehiago: biderkatu.","Uno solo, más tiempo: multiplica.","الواحد يحتاج وقتًا أطول: اضرب.","One person alone takes more time: multiply."),explanation:c("$8\\cdot 3=24$")},{id:11,stage:"inverse",prompt:n("Nekazari batek 25 behi 18 egunez elikatzeko pentsua du. Zenbat egunez elikatuko lituzke 45 behi?","Un granjero tiene pienso para 25 vacas durante 18 días. ¿Cuántos días alimentaría a 45 vacas?","لدى مزارع علف يكفي 25 بقرة مدة 18 يومًا. كم يومًا يكفي 45 بقرة؟","A farmer has feed for 25 cows for 18 days. How many days would it feed 45 cows?"),expected:h(10),hint:n("Behi gehiago, egun gutxiago: $25\\cdot 18=45\\cdot x$.","Más vacas, menos días: $25\\cdot 18=45\\cdot x$.","أبقار أكثر، أيام أقل: $25\\cdot 18=45\\cdot x$.","More cows, fewer days: $25\\cdot 18=45\\cdot x$."),explanation:c("$25\\cdot 18=450\\ \\to\\ 450\\mathbin{:}45=10$")},{id:12,stage:"inverse",prompt:n("Minutuko $2{,}5$ litroko txorrota batek 40 minutu behar ditu ontzi bat betetzeko. Zenbat minutu beharko lituzke minutuko 4 litrorekin?","Un grifo de $2{,}5$ litros por minuto tarda 40 minutos en llenar un depósito. ¿Cuánto tardaría con 4 litros por minuto?","صنبور تدفقه $2{,}5$ لتر في الدقيقة يملأ خزانًا في 40 دقيقة. كم دقيقة يحتاج بتدفق 4 لترات في الدقيقة؟","A tap that gives $2{,}5$ litres per minute takes 40 minutes to fill a tank. How long would it take at 4 litres per minute?"),expected:h(25),hint:n("Biderkadura beti bera: $2{,}5\\cdot 40$.","El producto siempre igual: $2{,}5\\cdot 40$.","حاصل الضرب ثابت: $2{,}5\\cdot 40$.","The product is always the same: $2{,}5\\cdot 40$."),explanation:c("$2{,}5\\cdot 40=100\\ \\to\\ 100\\mathbin{:}4=25$")},{id:13,stage:"percent",prompt:n("Kalkulatu 300en % 7.","Calcula el 7 % de 300.","احسب 7٪ من 300.","Work out 7% of 300."),expected:h(21),hint:n("Biderkatu 7z eta zatitu 100ez.","Multiplica por 7 y divide entre 100.","اضرب في 7 واقسم على 100.","Multiply by 7 and divide by 100."),explanation:c("$300\\cdot 7\\mathbin{:}100=21$")},{id:14,stage:"percent",prompt:n("480 ardiko artalde batean 120 ilea moztuta daude. Zer ehuneko da? (Idatzi zenbakia, % gabe.)","En un rebaño de 480 ovejas se han esquilado 120. ¿Qué porcentaje es? (Escribe el número, sin %.)","في قطيع من 480 نعجة جُزّ صوف 120. ما النسبة المئوية؟ (اكتب العدد بلا ٪.)","In a flock of 480 sheep, 120 have been sheared. What percentage is that? (Write the number, without %.)"),expected:h(25),hint:n("Zatia zati osoa, bider 100.","La parte entre el total, por 100.","الجزء على الكل، في 100.","The part divided by the total, times 100."),explanation:c("$120\\mathbin{:}480=0{,}25\\ \\to\\ 0{,}25\\cdot 100=25$")},{id:15,stage:"percent",prompt:n("Zer ehuneko da $0{,}07$? (Idatzi zenbakia, % gabe.)","¿Qué porcentaje es $0{,}07$? (Escribe el número, sin %.)","ما النسبة المئوية المساوية لـ $0{,}07$؟ (اكتب العدد بلا ٪.)","What percentage is $0{,}07$? (Write the number, without %.)"),expected:h(7),hint:n("Bider 100: koma bi toki eskuinera.","Por 100: la coma dos lugares a la derecha.","في 100: الفاصلة منزلتين يمينًا.","Times 100: the decimal point moves two places to the right."),explanation:c("$0{,}07\\cdot 100=7$")},{id:16,stage:"percent",prompt:n("Erlezain batek 54 erlauntzetako eztia atera du, erlategiaren % 30. Zenbat erlauntza ditu guztira?","Un apicultor ha sacado la miel de 54 colmenas, el 30 % del colmenar. ¿Cuántas colmenas tiene en total?","استخرج نحّال عسل 54 خلية، وهي 30٪ من المنحل. كم خلية عنده في المجموع؟","A beekeeper has taken the honey from 54 hives, which is 30% of the apiary. How many hives does he have in total?"),expected:h(180),hint:n("% 1: $54\\mathbin{:}30$.","El 1 %: $54\\mathbin{:}30$.","1٪: $54\\mathbin{:}30$.","1%: $54\\mathbin{:}30$."),explanation:c("$54\\mathbin{:}30=1{,}8\\ \\to\\ 1{,}8\\cdot 100=180$")},{id:17,stage:"changes",prompt:n("Zapatilek 60 € balio dute eta % 15 deskontatu dute. Zenbat ordaintzen da?","Unas zapatillas cuestan 60 € y les descuentan el 15 %. ¿Cuánto se paga?","ثمن حذاء رياضي 60 € وخُصم منه 15٪. كم يُدفع؟","A pair of trainers costs €60 and they are reduced by 15%. How much do you pay?"),expected:h(51),hint:n("Deskontua: $60\\cdot 15\\mathbin{:}100$.","El descuento: $60\\cdot 15\\mathbin{:}100$.","الخصم: $60\\cdot 15\\mathbin{:}100$.","The discount: $60\\cdot 15\\mathbin{:}100$."),explanation:c("$60\\cdot 15\\mathbin{:}100=9\\ \\to\\ 60-9=51$")},{id:18,stage:"changes",prompt:n("75 €-ko isun bati % 15eko errekargua jarri diote. Zenbat ordaindu behar da guztira?","A una multa de 75 € le ponen un recargo del 15 %. ¿Cuánto hay que pagar en total?","فُرض على مخالفة قيمتها 75 € رسم إضافي قدره 15٪. كم يجب دفعه في المجموع؟","A €75 fine gets a 15% surcharge. How much must be paid in total?"),expected:T("86,25"),hint:n("Errekargua kalkulatu eta batu.","Calcula el recargo y súmalo.","احسب الرسم واجمعه.","Work out the surcharge and add it."),explanation:c("$75\\cdot 15\\mathbin{:}100=11{,}25\\ \\to\\ 75+11{,}25=86{,}25$")},{id:19,stage:"changes",prompt:n("Beroki bat % 10 merkatu didate. Prezioaren zer ehuneko ordaintzen dut? (Idatzi zenbakia, % gabe.)","Me rebajan un abrigo un 10 %. ¿Qué porcentaje del precio pago? (Escribe el número, sin %.)","خُفّض لي معطف بنسبة 10٪. ما النسبة التي أدفعها من السعر؟ (اكتب العدد بلا ٪.)","A coat is reduced by 10%. What percentage of the price do I pay? (Write the number, without %.)"),expected:h(90),hint:n("Osoa % 100 da.","El total es el 100 %.","الكل هو 100٪.","The total is 100%."),explanation:c("$100-10=90$")},{id:20,stage:"changes",prompt:n("Nekazari batek 8400 kg sagar bildu ditu. % 80 supermerkatu-kate bati saldu dio eta % 15 fruta-denda bati; gainerakoa bota egin du. Zenbat kilo bota ditu?","Un agricultor recoge 8400 kg de manzanas. Vende el 80 % a una cadena de supermercados y el 15 % a una frutería; el resto lo desecha. ¿Cuántos kilos desecha?","جمع مزارع 8400 كغ من التفاح. باع 80٪ لسلسلة متاجر و15٪ لدكان فاكهة، وتخلّص من الباقي. كم كيلوغرامًا تخلّص منه؟","A farmer picks 8400 kg of apples. He sells 80% to a supermarket chain and 15% to a greengrocer's; he throws away the rest. How many kilos does he throw away?"),expected:h(420),hint:n("Gainerakoa: $100-80-15$ ehuneko.","El resto: $100-80-15$ por ciento.","الباقي: $100-80-15$ بالمئة.","The rest: $100-80-15$ per cent."),explanation:c("$100-80-15=5\\ \\to\\ 8400\\cdot 5\\mathbin{:}100=420$")}],ba=[{id:101,stage:"ratios",points:10,context:"starter",prompt:n("Aurkitu $x$: $\\frac{7}{21}=\\frac{x}{63}$.","Halla $x$: $\\frac{7}{21}=\\frac{x}{63}$.","أوجد $x$: $\\frac{7}{21}=\\frac{x}{63}$.","Find $x$: $\\frac{7}{21}=\\frac{x}{63}$."),expected:h(21),hint:n("$21\\cdot x=7\\cdot 63$.","$21\\cdot x=7\\cdot 63$.","$21\\cdot x=7\\cdot 63$.","$21\\cdot x=7\\cdot 63$."),explanation:c("$21\\cdot x=7\\cdot 63=441\\ \\to\\ x=441\\mathbin{:}21=21$")},{id:102,stage:"ratios",points:20,context:"advanced",prompt:n("$\\frac{1}{2}=\\frac{2}{4}=\\frac{3}{6}=\\frac{4}{8}$. Kalkulatu aurrekarien batura zati ondorengoen batura.","$\\frac{1}{2}=\\frac{2}{4}=\\frac{3}{6}=\\frac{4}{8}$. Calcula la suma de los antecedentes entre la suma de los consecuentes.","$\\frac{1}{2}=\\frac{2}{4}=\\frac{3}{6}=\\frac{4}{8}$. احسب مجموع المقدَّمات على مجموع التوالي.","$\\frac{1}{2}=\\frac{2}{4}=\\frac{3}{6}=\\frac{4}{8}$. Work out the sum of the antecedents divided by the sum of the consequents."),expected:T("0,5"),hint:n("$1+2+3+4$ eta $2+4+6+8$.","$1+2+3+4$ y $2+4+6+8$.","$1+2+3+4$ و$2+4+6+8$.","$1+2+3+4$ and $2+4+6+8$."),explanation:c("$\\frac{1+2+3+4}{2+4+6+8}=\\frac{10}{20}=0{,}5$")},{id:103,stage:"direct",points:10,context:"starter",prompt:n("12 fotokopiak $0{,}50$ € balio dute. Zenbat balio dute 30 fotokopiak?","12 fotocopias cuestan $0{,}50$ €. ¿Cuánto cuestan 30 fotocopias?","ثمن 12 نسخة مصوّرة $0{,}50$ €. كم ثمن 30 نسخة؟","12 photocopies cost €$0{,}50$. How much do 30 photocopies cost?"),expected:T("1,25"),hint:n("$\\frac{12}{0{,}50}=\\frac{30}{x}$.","$\\frac{12}{0{,}50}=\\frac{30}{x}$.","$\\frac{12}{0{,}50}=\\frac{30}{x}$.","$\\frac{12}{0{,}50}=\\frac{30}{x}$."),explanation:c("$x=\\frac{30\\cdot 0{,}50}{12}=\\frac{15}{12}=1{,}25$")},{id:104,stage:"direct",points:20,context:"advanced",prompt:n("Hamar ogi-barrak $4{,}75$ € balio dute. Zenbat balio dute 24 barrak?","Diez barras de pan cuestan $4{,}75$ €. ¿Cuánto cuestan 24 barras?","ثمن عشرة أرغفة $4{,}75$ €. كم ثمن 24 رغيفًا؟","Ten loaves of bread cost €$4{,}75$. How much do 24 loaves cost?"),expected:T("11,4"),hint:n("Barra batek: $4{,}75\\mathbin{:}10$.","Una barra: $4{,}75\\mathbin{:}10$.","الرغيف الواحد: $4{,}75\\mathbin{:}10$.","One loaf: $4{,}75\\mathbin{:}10$."),explanation:c("$4{,}75\\mathbin{:}10=0{,}475\\ \\to\\ 0{,}475\\cdot 24=11{,}4$")},{id:105,stage:"direct",points:30,context:"master",prompt:n("20 € gastatzeagatik 3 deskontu-kupoi ematen dizkizute. Zenbat kupoi 140 € gastatzeagatik?","Por cada 20 € de gasto te dan 3 cupones descuento. ¿Cuántos cupones te dan por un gasto de 140 €?","مقابل كل 20 € من المشتريات تحصل على 3 قسائم خصم. كم قسيمة مقابل 140 €؟","For every €20 you spend, you get 3 discount vouchers. How many vouchers do you get for spending €140?"),expected:h(21),hint:n("$\\frac{20}{3}=\\frac{140}{x}$.","$\\frac{20}{3}=\\frac{140}{x}$.","$\\frac{20}{3}=\\frac{140}{x}$.","$\\frac{20}{3}=\\frac{140}{x}$."),explanation:c("$20\\cdot x=140\\cdot 3=420\\ \\to\\ x=420\\mathbin{:}20=21$")},{id:106,stage:"inverse",points:20,context:"advanced",prompt:n("Ur-biltegi bat 18 ordutan betetzen da minutuko 360 litro botatzen dituen txorrota batekin. Zenbat ordu beharko lirateke minutuko 270 litrorekin?","Un depósito se llena en 18 horas con un grifo del que salen 360 litros por minuto. ¿Cuántas horas tardaría con 270 litros por minuto?","يمتلئ خزان في 18 ساعة بصنبور يصب 360 لترًا في الدقيقة. كم ساعة يحتاج بتدفق 270 لترًا في الدقيقة؟","A tank fills in 18 hours with a tap that gives 360 litres per minute. How many hours would it take with 270 litres per minute?"),expected:h(24),hint:n("Emari gutxiago, denbora gehiago: $360\\cdot 18=270\\cdot x$.","Menos caudal, más tiempo: $360\\cdot 18=270\\cdot x$.","تدفق أقل، زمن أطول: $360\\cdot 18=270\\cdot x$.","Less flow rate, more time: $360\\cdot 18=270\\cdot x$."),explanation:c("$360\\cdot 18=6480\\ \\to\\ 6480\\mathbin{:}270=24$")},{id:107,stage:"inverse",points:30,context:"master",prompt:n("Auto batek 39 minututan egin du A eta B hirien arteko bidea, 95 km/h-ko batez besteko abiaduran. Zenbat minutu beharko ditu kamioi batek 65 km/h-ra?","Un coche ha hecho el recorrido entre las ciudades A y B en 39 minutos a 95 km/h de media. ¿Cuántos minutos tardará un camión a 65 km/h?","قطعت سيارة الطريق بين المدينتين أ وب في 39 دقيقة بسرعة متوسطة 95 كم/س. كم دقيقة تحتاج شاحنة بسرعة 65 كم/س؟","A car has covered the journey between cities A and B in 39 minutes at an average of 95 km/h. How many minutes will a lorry take at 65 km/h?"),expected:h(57),hint:n("Alderantzizkoa: $95\\cdot 39=65\\cdot x$.","Inversa: $95\\cdot 39=65\\cdot x$.","عكسي: $95\\cdot 39=65\\cdot x$.","Inverse: $95\\cdot 39=65\\cdot x$."),explanation:c("$95\\cdot 39=3705\\ \\to\\ 3705\\mathbin{:}65=57$")},{id:108,stage:"inverse",points:20,context:"advanced",prompt:n("10 igeltserok horma bat 45 egunetan eraikitzen dute. Zenbat igeltsero beharko lirateke 5 egunetan amaitzeko?","10 albañiles construyen un muro en 45 días. ¿Cuántos albañiles harían falta para terminarlo en 5 días?","يبني 10 بنّائين جدارًا في 45 يومًا. كم بنّاءً نحتاج لإنهائه في 5 أيام؟","10 bricklayers build a wall in 45 days. How many bricklayers would be needed to finish it in 5 days?"),expected:h(90),hint:n("$10\\cdot 45=x\\cdot 5$.","$10\\cdot 45=x\\cdot 5$.","$10\\cdot 45=x\\cdot 5$.","$10\\cdot 45=x\\cdot 5$."),explanation:c("$10\\cdot 45=450\\ \\to\\ 450\\mathbin{:}5=90$")},{id:109,stage:"percent",points:10,context:"starter",prompt:n("Zein zenbakiren % 8 da 24?","¿De qué número es 24 el 8 %?","العدد 24 هو 8٪ من أي عدد؟","24 is 8% of what number?"),expected:h(300),hint:n("% 1: $24\\mathbin{:}8$.","El 1 %: $24\\mathbin{:}8$.","1٪: $24\\mathbin{:}8$.","1%: $24\\mathbin{:}8$."),explanation:c("$24\\mathbin{:}8=3\\ \\to\\ 3\\cdot 100=300$")},{id:110,stage:"percent",points:20,context:"advanced",prompt:n("Kalkulatu 50en % $37{,}5$.","Calcula el $37{,}5$ % de 50.","احسب $37{,}5$٪ من 50.","Work out $37{,}5$% of 50."),expected:T("18,75"),hint:n("$50\\cdot 37{,}5\\mathbin{:}100$.","$50\\cdot 37{,}5\\mathbin{:}100$.","$50\\cdot 37{,}5\\mathbin{:}100$.","$50\\cdot 37{,}5\\mathbin{:}100$."),explanation:c("$50\\cdot 37{,}5=1875\\ \\to\\ 1875\\mathbin{:}100=18{,}75$")},{id:111,stage:"percent",points:30,context:"master",prompt:n("1. DBHn mutilak nesken % 80 dira. 30 neska badaude, zenbat mutil daude?","En 1.º ESO, los chicos son el 80 % del número de chicas. Si hay 30 chicas, ¿cuántos chicos hay?","في الصف الأول عدد الأولاد 80٪ من عدد البنات. إذا كانت البنات 30، فكم عدد الأولاد؟","In 1st ESO, the boys are 80% of the number of girls. If there are 30 girls, how many boys are there?"),expected:h(24),hint:n("Nesken % 80: 30en % 80.","El 80 % de las chicas: el 80 % de 30.","80٪ من البنات: 80٪ من 30.","80% of the girls: 80% of 30."),explanation:c("$30\\cdot 80\\mathbin{:}100=24$")},{id:112,stage:"changes",points:10,context:"starter",prompt:n("Ikasleen % 92k azterketa gainditu dute. Zer ehunekok ez du gainditu? (Idatzi zenbakia, % gabe.)","El 92 % de los alumnos ha aprobado un examen. ¿Qué porcentaje no ha aprobado? (Escribe el número, sin %.)","نجح 92٪ من التلاميذ في امتحان. ما نسبة من لم ينجح؟ (اكتب العدد بلا ٪.)","92% of the students passed an exam. What percentage did not pass? (Write the number, without the % sign.)"),expected:h(8),hint:n("Osoa % 100.","El total es el 100 %.","الكل 100٪.","The total is 100%."),explanation:c("$100-92=8$")},{id:113,stage:"changes",points:20,context:"advanced",prompt:n("3000 marmelada-poteko eskaera batean: % 25 marrubi, % 45 aran, % 20 mertxika eta gainerakoa laranja. Zenbat pote dira laranjazkoak?","En un pedido de 3000 botes de mermelada: el 25 % son de fresa, el 45 % de ciruela, el 20 % de melocotón y el resto de naranja. ¿Cuántos botes son de naranja?","في طلبية من 3000 علبة مربى: 25٪ فراولة و45٪ برقوق و20٪ خوخ والباقي برتقال. كم علبة برتقال؟","In an order of 3,000 jars of jam: 25% are strawberry, 45% plum, 20% peach and the rest orange. How many jars are orange?"),expected:h(300),hint:n("Laranjazkoak: $100-25-45-20$ ehuneko.","Las de naranja: $100-25-45-20$ por ciento.","البرتقال: $100-25-45-20$ بالمئة.","The orange ones: $100-25-45-20$ per cent."),explanation:c("$100-25-45-20=10\\ \\to\\ 3000\\cdot 10\\mathbin{:}100=300$")},{id:114,stage:"changes",points:30,context:"master",prompt:n("20000 biztanleko herri batean % 35 alokairuan bizi da. Zenbat pertsona bizi dira etxe propioan?","En un pueblo de 20000 habitantes, el 35 % vive de alquiler. ¿Cuántas personas viven en casa propia?","في بلدة من 20000 نسمة يعيش 35٪ في بيوت مستأجرة. كم شخصًا يعيش في بيت يملكه؟","In a town of 20,000 inhabitants, 35% live in rented homes. How many people live in a home they own?"),expected:h(13e3),hint:n("Etxe propioan: $100-35$ ehuneko.","En casa propia: $100-35$ por ciento.","في بيت مملوك: $100-35$ بالمئة.","Homes they own: $100-35$ per cent."),explanation:c("$100-35=65\\ \\to\\ 20000\\cdot 65\\mathbin{:}100=13000$")}],ka=[{id:"ratios",title:n("Magnitudeak eta arrazoiak","Magnitudes y razones","المقادير والنسب","Quantities and ratios"),items:[{id:1,difficulty:"easy",question:n("Magnitudeak dira ala ez? a) Patata-zaku baten pisua; b) maitasuna; c) zure mahaiaren neurriak; d) igerileku bateko ur-litroak; e) barrea.","¿Son magnitudes o no? a) El peso de un saco de patatas; b) el cariño; c) las dimensiones de tu pupitre; d) los litros de agua de una piscina; e) la risa.","هل هي مقادير أم لا؟ أ) وزن كيس بطاطا؛ ب) المحبة؛ ج) أبعاد طاولتك؛ د) لترات الماء في مسبح؛ هـ) الضحك.","Are they quantities or not? a) The weight of a sack of potatoes; b) affection; c) the dimensions of your desk; d) the litres of water in a swimming pool; e) laughter."),solution:n("a), c) eta d) magnitudeak dira (kg, cm, l); b) eta e) ez.","a), c) y d) son magnitudes (kg, cm, l); b) y e), no.","أ) وج) ود) مقادير (كغ، سم، ل)؛ أما ب) وهـ) فلا.","a), c) and d) are quantities (kg, cm, l); b) and e) are not.")},{id:2,difficulty:"easy",question:n("Idatzi bi neurri-unitate: a) bi herriren arteko distantzia; b) botila baten edukia; c) bizikleta baten prezioa.","Indica dos unidades de medida: a) la distancia entre dos pueblos; b) el contenido de una botella; c) el precio de una bicicleta.","اذكر وحدتي قياس: أ) المسافة بين قريتين؛ ب) سعة زجاجة؛ ج) ثمن دراجة.","Name two units of measurement: a) the distance between two towns; b) the capacity of a bottle; c) the price of a bicycle."),solution:n("a) km eta m; b) l eta cl; c) € eta zentimoak.","a) km y m; b) l y cl; c) € y céntimos.","أ) كم وم؛ ب) ل وسل؛ ج) € والسنتات.","a) km and m; b) l and cl; c) € and cents.")},{id:3,difficulty:"easy",question:n("Kalkulatu arrazoiaren balioa: 5 € eta 2 kg.","Calcula el valor de la razón: 5 € y 2 kg.","احسب قيمة النسبة: 5 € و2 كغ.","Work out the value of the ratio: €5 and 2 kg."),solution:c("$\\frac{5}{2}=2{,}5$"),answer:{expected:T("2,5")}},{id:4,difficulty:"medium",question:n("Aurkitu $x$: $\\frac{6}{10}=\\frac{9}{x}$.","Halla $x$: $\\frac{6}{10}=\\frac{9}{x}$.","أوجد $x$: $\\frac{6}{10}=\\frac{9}{x}$.","Find $x$: $\\frac{6}{10}=\\frac{9}{x}$."),solution:c("$6\\cdot x=10\\cdot 9=90\\ \\to\\ x=90\\mathbin{:}6=15$"),answer:{expected:h(15)}},{id:5,difficulty:"medium",question:n("Aurkitu $x$: $\\frac{x}{4}=\\frac{10}{8}$.","Halla $x$: $\\frac{x}{4}=\\frac{10}{8}$.","أوجد $x$: $\\frac{x}{4}=\\frac{10}{8}$.","Find $x$: $\\frac{x}{4}=\\frac{10}{8}$."),solution:c("$8\\cdot x=4\\cdot 10=40\\ \\to\\ x=40\\mathbin{:}8=5$"),answer:{expected:h(5)}},{id:6,difficulty:"medium",question:n("Osatu arrazoi berdinen seriea: $\\frac{2}{3}=\\frac{6}{\\square}=\\frac{\\square}{12}=\\frac{10}{\\square}$.","Completa la serie de razones iguales: $\\frac{2}{3}=\\frac{6}{\\square}=\\frac{\\square}{12}=\\frac{10}{\\square}$.","أكمل سلسلة النسب المتساوية: $\\frac{2}{3}=\\frac{6}{\\square}=\\frac{\\square}{12}=\\frac{10}{\\square}$.","Complete the series of equal ratios: $\\frac{2}{3}=\\frac{6}{\\square}=\\frac{\\square}{12}=\\frac{10}{\\square}$."),solution:c("$\\frac{2}{3}=\\frac{6}{9}=\\frac{8}{12}=\\frac{10}{15}$")},{id:7,difficulty:"medium",question:n("Zatikiak ala arrazoiak? a) $\\frac{2}{5}$; b) $\\frac{0{,}5}{9}$; c) $\\frac{35}{8}$; d) $\\frac{4}{2{,}5}$.","¿Fracciones o razones? a) $\\frac{2}{5}$; b) $\\frac{0{,}5}{9}$; c) $\\frac{35}{8}$; d) $\\frac{4}{2{,}5}$.","كسور أم نسب؟ أ) $\\frac{2}{5}$؛ ب) $\\frac{0{,}5}{9}$؛ ج) $\\frac{35}{8}$؛ د) $\\frac{4}{2{,}5}$.","Fractions or ratios? a) $\\frac{2}{5}$; b) $\\frac{0{,}5}{9}$; c) $\\frac{35}{8}$; d) $\\frac{4}{2{,}5}$."),solution:n("a) eta c) zatikiak eta arrazoiak dira; b) eta d) arrazoiak bakarrik, hamartarrak dituztelako.","a) y c) son fracciones y razones; b) y d), solo razones, porque tienen decimales.","أ) وج) كسران ونسبتان؛ أما ب) ود) فنسبتان فقط لأن فيهما أعدادًا عشرية.","a) and c) are fractions and ratios; b) and d) are only ratios, because they have decimals.")},{id:8,difficulty:"hard",question:n("Aurkitu $x$: $\\frac{0{,}5}{0{,}6}=\\frac{7{,}5}{x}$.","Halla $x$: $\\frac{0{,}5}{0{,}6}=\\frac{7{,}5}{x}$.","أوجد $x$: $\\frac{0{,}5}{0{,}6}=\\frac{7{,}5}{x}$.","Find $x$: $\\frac{0{,}5}{0{,}6}=\\frac{7{,}5}{x}$."),solution:c("$0{,}5\\cdot x=0{,}6\\cdot 7{,}5=4{,}5\\ \\to\\ x=4{,}5\\mathbin{:}0{,}5=9$"),answer:{expected:h(9)}},{id:9,difficulty:"hard",question:n("Egiaztatu: $\\frac{3}{6}=\\frac{4}{8}$ proportzio bat da?","Comprueba: ¿es $\\frac{3}{6}=\\frac{4}{8}$ una proporción?","تحقّق: هل $\\frac{3}{6}=\\frac{4}{8}$ تناسب؟","Check: is $\\frac{3}{6}=\\frac{4}{8}$ a proportion?"),solution:n("Bai: $3\\cdot 8=24$ eta $6\\cdot 4=24$.","Sí: $3\\cdot 8=24$ y $6\\cdot 4=24$.","نعم: $3\\cdot 8=24$ و$6\\cdot 4=24$.","Yes: $3\\cdot 8=24$ and $6\\cdot 4=24$.")},{id:10,difficulty:"hard",question:n("$\\frac{6}{10}=\\frac{12}{20}=\\frac{18}{30}$. Kalkulatu aurrekarien batura zati ondorengoen batura.","$\\frac{6}{10}=\\frac{12}{20}=\\frac{18}{30}$. Calcula la suma de los antecedentes entre la de los consecuentes.","$\\frac{6}{10}=\\frac{12}{20}=\\frac{18}{30}$. احسب مجموع المقدَّمات على مجموع التوالي.","$\\frac{6}{10}=\\frac{12}{20}=\\frac{18}{30}$. Work out the sum of the antecedents divided by the sum of the consequents."),solution:c("$\\frac{6+12+18}{10+20+30}=\\frac{36}{60}=0{,}6$"),answer:{expected:T("0,6")}}]},{id:"direct",title:n("Proportzionaltasun zuzena","Proporcionalidad directa","التناسب الطردي","Direct proportion"),items:[{id:11,difficulty:"easy",question:n("Zuzenki proportzionalak dira? a) Laranja-kiloak eta prezioa; b) liburu baten orri kopurua eta pisua; c) ikasle baten adina eta altuera.","¿Son directamente proporcionales? a) Los kilos de naranjas y su precio; b) el número de hojas de un libro y su peso; c) la edad de un alumno y su altura.","هل هي متناسبة طرديًا؟ أ) كيلوغرامات البرتقال وثمنها؛ ب) عدد أوراق كتاب ووزنه؛ ج) عمر تلميذ وطوله.","Are they directly proportional? a) The kilos of oranges and their price; b) the number of pages in a book and its weight; c) a student's age and their height."),solution:n("a) eta b) bai; c) ez.","a) y b), sí; c), no.","أ) وب) نعم؛ ج) لا.","a) and b), yes; c), no.")},{id:12,difficulty:"easy",question:n("Zinema-sarrera batek 5 € balio du. Zenbat balio dute 8 sarrerak?","Una entrada de cine cuesta 5 €. ¿Cuánto cuestan 8 entradas?","ثمن تذكرة السينما 5 €. كم ثمن 8 تذاكر؟","A cinema ticket costs €5. How much do 8 tickets cost?"),solution:c("$5\\cdot 8=40$"),answer:{expected:h(40)}},{id:13,difficulty:"easy",question:n("Hiru txokolatinek 90 g pisatzen dute. Zenbat pisatzen dute bik?","Tres chocolatinas pesan 90 g. ¿Cuánto pesan dos?","تزن ثلاث قطع شوكولاتة 90 غ. كم تزن قطعتان؟","Three chocolate bars weigh 90 g. How much do two weigh?"),solution:c("$90\\mathbin{:}3=30\\ \\to\\ 30\\cdot 2=60$"),answer:{expected:h(60)}},{id:14,difficulty:"medium",question:n("Freskagarri-botila batek $3{,}50$ € balio du; 2 botilak, 6 €; 4 botilak, 11 €. Zuzenki proportzionalak dira?","1 botella de refresco cuesta $3{,}50$ €; 2 botellas, 6 €; 4 botellas, 11 €. ¿Son directamente proporcionales?","ثمن زجاجة مشروب $3{,}50$ €؛ وزجاجتين 6 €؛ و4 زجاجات 11 €. هل هي متناسبة طرديًا؟","1 bottle of fizzy drink costs €$3{,}50$; 2 bottles, €6; 4 bottles, €11. Are they directly proportional?"),solution:n("Ez: $\\frac{1}{3{,}50}\\neq\\frac{2}{6}$. Bi botilek 7 € balioko lukete.","No: $\\frac{1}{3{,}50}\\neq\\frac{2}{6}$. Dos botellas costarían 7 €.","لا: $\\frac{1}{3{,}50}\\neq\\frac{2}{6}$. كانت الزجاجتان ستكلفان 7 €.","No: $\\frac{1}{3{,}50}\\neq\\frac{2}{6}$. Two bottles would cost €7.")},{id:15,difficulty:"medium",question:n("Txorrota batek segundoko $0{,}2$ litro botatzen ditu. Zenbat litro 20 segundotan?","Un grifo arroja $0{,}2$ litros cada segundo. ¿Cuántos litros en 20 segundos?","يصبّ صنبور $0{,}2$ لتر كل ثانية. كم لترًا في 20 ثانية؟","A tap pours out $0{,}2$ litres every second. How many litres in 20 seconds?"),solution:c("$0{,}2\\cdot 20=4$"),answer:{expected:h(4)}},{id:16,difficulty:"medium",question:n("Lau txokolatina erosteagatik $9{,}20$ € ordaindu ditut. Zenbat ordainduko nituzke hiru erosita?","He pagado $9{,}20$ € por cuatro chocolatinas. ¿Cuánto habría pagado por tres?","دفعت $9{,}20$ € ثمن أربع قطع شوكولاتة. كم كنت سأدفع ثمن ثلاث؟","I paid €$9{,}20$ for four chocolate bars. How much would I have paid for three?"),solution:c("$x=\\frac{3\\cdot 9{,}20}{4}=6{,}9$"),answer:{expected:T("6,9")}},{id:17,difficulty:"medium",question:n("Txirrindulari batek 75 km egiten ditu 2 ordutan. Abiadura berean, zenbat km 5 ordutan?","Un ciclista recorre 75 km en 2 horas. A la misma velocidad, ¿cuántos km en 5 horas?","يقطع دراج 75 كم في ساعتين. بالسرعة نفسها، كم كيلومترًا في 5 ساعات؟","A cyclist travels 75 km in 2 hours. At the same speed, how many km in 5 hours?"),solution:c("$x=\\frac{5\\cdot 75}{2}=187{,}5$"),answer:{expected:T("187,5")}},{id:18,difficulty:"hard",question:n("Garbitzeko tunel batek 12 auto garbitzen ditu ordubetean (60 minutu). Zenbat minutu beharko ditu 25 autorentzat?","Un túnel de lavado limpia 12 coches en una hora (60 minutos). ¿Cuántos minutos tardará en lavar 25 coches?","يغسل نفق غسيل 12 سيارة في ساعة (60 دقيقة). كم دقيقة يحتاج لغسل 25 سيارة؟","A car wash cleans 12 cars in one hour (60 minutes). How many minutes will it take to wash 25 cars?"),solution:c("$60\\mathbin{:}12=5\\ \\to\\ 5\\cdot 25=125$"),answer:{expected:h(125)}},{id:19,difficulty:"hard",question:n("5 esne-botilak $3{,}75$ € balio dute. Zenbat balio du 36 botilako kaxa batek?","5 botellas de leche cuestan $3{,}75$ €. ¿Cuánto cuesta una caja de 36 botellas?","ثمن 5 زجاجات حليب $3{,}75$ €. كم ثمن صندوق من 36 زجاجة؟","5 bottles of milk cost €$3{,}75$. How much does a crate of 36 bottles cost?"),solution:c("$3{,}75\\mathbin{:}5=0{,}75\\ \\to\\ 0{,}75\\cdot 36=27$"),answer:{expected:h(27)}},{id:20,difficulty:"hard",question:n("Obra batean 2 langilek 5 m-ko zanga egiten dute. Erritmo berean, zenbat metro egingo dituzte beste 3 langile gehitzen badira?","En una obra, 2 obreros hacen una zanja de 5 m. Al mismo ritmo, ¿cuántos metros harán si se incorporan 3 obreros más?","في ورشة يحفر عاملان خندقًا طوله 5 م. بالوتيرة نفسها، كم مترًا يحفرون إذا انضم 3 عمال آخرون؟","On a building site, 2 workers dig a 5 m trench. At the same rate, how many metres will they dig if 3 more workers join them?"),solution:c("$2+3=5\\ \\to\\ 5\\mathbin{:}2=2{,}5\\ \\to\\ 2{,}5\\cdot 5=12{,}5$"),answer:{expected:T("12,5")}}]},{id:"inverse",title:n("Alderantzizko proportzionaltasuna","Proporcionalidad inversa","التناسب العكسي","Inverse proportion"),items:[{id:21,difficulty:"easy",question:n("Alderantziz proportzionalak dira? a) Auto baten abiadura eta distantzia jakin bat egiteko denbora; b) horma baten adreilu kopurua eta altuera; c) biltegi bat betetzen duten txorrotak eta denbora.","¿Son inversamente proporcionales? a) La velocidad de un coche y el tiempo en recorrer una distancia; b) el número de ladrillos de una pared y su altura; c) los grifos que llenan un depósito y el tiempo.","هل هي متناسبة عكسيًا؟ أ) سرعة سيارة والزمن اللازم لقطع مسافة؛ ب) عدد طوب جدار وارتفاعه؛ ج) الصنابير التي تملأ خزانًا والزمن.","Are they inversely proportional? a) The speed of a car and the time it takes to cover a distance; b) the number of bricks in a wall and its height; c) the number of taps filling a tank and the time it takes."),solution:n("a) eta c) bai; b) ez (zuzena da).","a) y c), sí; b), no (es directa).","أ) وج) نعم؛ ب) لا (طردي).","a) and c), yes; b), no (it is direct proportion).")},{id:22,difficulty:"easy",question:n("Belar-zama batek 3 zaldi elikatzen ditu 6 egunez. Zenbat egunez elikatuko luke zaldi bat?","Una carga de heno alimenta a 3 caballos durante 6 días. ¿Cuántos días alimentaría a un caballo?","حمولة تبن تطعم 3 خيول 6 أيام. كم يومًا تطعم حصانًا واحدًا؟","A load of hay feeds 3 horses for 6 days. How many days would it feed one horse?"),solution:c("$6\\cdot 3=18$"),answer:{expected:h(18)}},{id:23,difficulty:"easy",question:n("Osatu taula (alderantzizkoa): langileak 1, 2, 4, 5, 10; orduak 20, …","Completa la tabla (inversa): operarios 1, 2, 4, 5, 10; horas 20, …","أكمل الجدول (عكسي): العمال 1، 2، 4، 5، 10؛ الساعات 20، …","Complete the table (inverse): workers 1, 2, 4, 5, 10; hours 20, …"),solution:c("$20,\\ 10,\\ 5,\\ 4,\\ 2\\qquad 1\\cdot 20=2\\cdot 10=4\\cdot 5=5\\cdot 4=10\\cdot 2=20$")},{id:24,difficulty:"medium",question:n("Hiru igeltserok horma bat 8 ordutan zarpiatzen dute. Zenbat ordu beharko lituzkete laurek?","Tres albañiles enfoscan una pared en 8 horas. ¿Cuántas horas tardarían cuatro?","يليّس ثلاثة بنّائين جدارًا في 8 ساعات. كم ساعة يحتاج أربعة؟","Three bricklayers plaster a wall in 8 hours. How many hours would four take?"),solution:c("$8\\cdot 3=24\\ \\to\\ 24\\mathbin{:}4=6$"),answer:{expected:h(6)}},{id:25,difficulty:"medium",question:n("Belar-zama batek 3 zaldi elikatzen ditu 6 egunez. Zenbat zaldi behar dira 2 egunean jateko?","Una carga de heno alimenta a 3 caballos durante 6 días. ¿Cuántos caballos hacen falta para consumirla en 2 días?","حمولة تبن تطعم 3 خيول 6 أيام. كم حصانًا يلزم لاستهلاكها في يومين؟","A load of hay feeds 3 horses for 6 days. How many horses are needed to use it up in 2 days?"),solution:c("$3\\cdot 6=18\\ \\to\\ 18\\mathbin{:}2=9$"),answer:{expected:h(9)}},{id:26,difficulty:"medium",question:n("Txorrota batek minutuko 3 litro botatzen ditu eta 15 minututan betetzen du upel bat. Zenbat minutu minutuko 12 litrorekin?","Un grifo vierte 3 litros por minuto y llena un tonel en 15 minutos. ¿Cuántos minutos con 12 litros por minuto?","يصب صنبور 3 لترات في الدقيقة ويملأ برميلًا في 15 دقيقة. كم دقيقة بتدفق 12 لترًا في الدقيقة؟","A tap pours 3 litres per minute and fills a barrel in 15 minutes. How many minutes would it take at 12 litres per minute?"),solution:c("$3\\cdot 15=45\\ \\to\\ 45\\mathbin{:}12=3{,}75$"),answer:{expected:T("3,75")}},{id:27,difficulty:"medium",question:n("Ibiltari batek 30 minutu behar ditu 4 km/h-ra. Zenbat minutu txirrindulari batek 15 km/h-ra?","Un paseante tarda 30 minutos a 4 km/h. ¿Cuántos minutos tarda un ciclista a 15 km/h?","يحتاج ماشٍ 30 دقيقة بسرعة 4 كم/س. كم دقيقة يحتاج دراج بسرعة 15 كم/س؟","A walker takes 30 minutes at 4 km/h. How many minutes does a cyclist take at 15 km/h?"),solution:c("$4\\cdot 30=120\\ \\to\\ 120\\mathbin{:}15=8$"),answer:{expected:h(8)}},{id:28,difficulty:"hard",question:n("Ur-biltegi bat 18 ordutan betetzen da minutuko 360 litrorekin. Zenbat ordu minutuko 630 litrorekin?","Un depósito se llena en 18 horas con 360 litros por minuto. ¿Cuántas horas con 630 litros por minuto?","يمتلئ خزان في 18 ساعة بتدفق 360 لترًا في الدقيقة. كم ساعة بتدفق 630 لترًا في الدقيقة؟","A tank fills in 18 hours at 360 litres per minute. How many hours at 630 litres per minute?"),solution:c("$360\\cdot 18=6480\\ \\to\\ 6480\\mathbin{:}630=\\frac{72}{7}\\approx 10{,}29$")},{id:29,difficulty:"hard",question:n("10 igeltserok horma bat 45 egunetan eraikitzen dute. Zenbat egun beharko lituzkete 25 igeltserok?","10 albañiles construyen un muro en 45 días. ¿Cuántos días tardarían 25 albañiles?","يبني 10 بنّائين جدارًا في 45 يومًا. كم يومًا يحتاج 25 بنّاءً؟","10 bricklayers build a wall in 45 days. How many days would 25 bricklayers take?"),solution:c("$10\\cdot 45=450\\ \\to\\ 450\\mathbin{:}25=18$"),answer:{expected:h(18)}},{id:30,difficulty:"hard",question:n("Egia ala gezurra? Belar-zama bat 3 zaldirentzat 6 egunerako bada, 6 zaldirentzat 3 egunerako da.","¿Verdadero o falso? Si una carga de heno dura 6 días a 3 caballos, a 6 caballos les dura 3 días.","صحيح أم خطأ؟ إذا كفت حمولة تبن 3 خيول 6 أيام، فإنها تكفي 6 خيول 3 أيام.","True or false? If a load of hay lasts 6 days for 3 horses, it lasts 3 days for 6 horses."),solution:n("Egia: $3\\cdot 6=6\\cdot 3=18$.","Verdadero: $3\\cdot 6=6\\cdot 3=18$.","صحيح: $3\\cdot 6=6\\cdot 3=18$.","True: $3\\cdot 6=6\\cdot 3=18$.")}]},{id:"percent",title:n("Ehunekoak","Porcentajes","النسب المئوية","Percentages"),items:[{id:31,difficulty:"easy",question:n("Idatzi zatiki eta hamartar gisa: a) % 85; b) % 9; c) % 38.","Escribe como fracción y como decimal: a) 85 %; b) 9 %; c) 38 %.","اكتب كسرًا وعددًا عشريًا: أ) 85٪؛ ب) 9٪؛ ج) 38٪.","Write as a fraction and as a decimal: a) 85%; b) 9%; c) 38%."),solution:c("a) $\\frac{85}{100}=0{,}85$; b) $\\frac{9}{100}=0{,}09$; c) $\\frac{38}{100}=0{,}38$")},{id:32,difficulty:"easy",question:n("Kalkulatu buruz: a) 100en % 30; b) 200en % 30; c) 300en % 30.","Calcula mentalmente: a) 30 % de 100; b) 30 % de 200; c) 30 % de 300.","احسب ذهنيًا: أ) 30٪ من 100؛ ب) 30٪ من 200؛ ج) 30٪ من 300.","Work out in your head: a) 30% of 100; b) 30% of 200; c) 30% of 300."),solution:c("a) $30$; b) $60$; c) $90$")},{id:33,difficulty:"easy",question:n("Kalkulatu 400en % 25.","Calcula el 25 % de 400.","احسب 25٪ من 400.","Work out 25% of 400."),solution:c("$400\\mathbin{:}4=100$"),answer:{expected:h(100)}},{id:34,difficulty:"medium",question:n("Kalkulatu 560ren % 17.","Calcula el 17 % de 560.","احسب 17٪ من 560.","Work out 17% of 560."),solution:c("$560\\cdot 17\\mathbin{:}100=95{,}2$"),answer:{expected:T("95,2")}},{id:35,difficulty:"medium",question:n("Idatzi ehuneko gisa: a) $0{,}16$; b) $0{,}03$; c) $\\frac{3}{4}$; d) $0{,}625$.","Expresa en porcentaje: a) $0{,}16$; b) $0{,}03$; c) $\\frac{3}{4}$; d) $0{,}625$.","عبّر بالنسبة المئوية: أ) $0{,}16$؛ ب) $0{,}03$؛ ج) $\\frac{3}{4}$؛ د) $0{,}625$.","Express as a percentage: a) $0{,}16$; b) $0{,}03$; c) $\\frac{3}{4}$; d) $0{,}625$."),solution:n("a) % 16; b) % 3; c) % 75; d) % $62{,}5$.","a) 16 %; b) 3 %; c) 75 %; d) $62{,}5$ %.","أ) 16٪؛ ب) 3٪؛ ج) 75٪؛ د) $62{,}5$٪.","a) 16%; b) 3%; c) 75%; d) $62{,}5$%.")},{id:36,difficulty:"medium",question:n("Klasean 30 ikasle daude eta % 40 jantokian geratzen da. Zenbat dira?","En clase hay 30 alumnos y el 40 % se queda al comedor. ¿Cuántos son?","في الصف 30 تلميذًا ويبقى 40٪ منهم في المطعم. كم عددهم؟","There are 30 students in class and 40% stay for lunch. How many students stay for lunch?"),solution:c("$30\\cdot 40\\mathbin{:}100=12$"),answer:{expected:h(12)}},{id:37,difficulty:"medium",question:n("Zer ehuneko da 200etik 24? (Idatzi zenbakia, % gabe.)","¿Qué porcentaje es 24 de 200? (Escribe el número, sin %.)","ما النسبة المئوية لـ 24 من 200؟ (اكتب العدد بلا ٪.)","What percentage is 24 of 200? (Write the number, without the % sign.)"),solution:c("$24\\mathbin{:}200=0{,}12\\ \\to\\ 0{,}12\\cdot 100=12$"),answer:{expected:h(12)}},{id:38,difficulty:"hard",question:n("Zein zenbakiren % 70 da 280?","¿De qué número es 280 el 70 %?","العدد 280 هو 70٪ من أي عدد؟","280 is 70% of what number?"),solution:c("$280\\mathbin{:}70=4\\ \\to\\ 4\\cdot 100=400$"),answer:{expected:h(400)}},{id:39,difficulty:"hard",question:n("24000 m²-ko urbanizazio baten % 35 lorategia da. Zenbat m² dira lorategiak?","Una urbanización de 24000 m² tiene el 35 % ajardinado. ¿Cuántos m² ocupan los jardines?","مجمّع سكني مساحته 24000 م² منها 35٪ حدائق. كم م² تشغل الحدائق؟","A housing estate of 24,000 m² has 35% landscaped as gardens. How many m² do the gardens cover?"),solution:c("$24000\\cdot 35\\mathbin{:}100=8400$"),answer:{expected:h(8400)}},{id:40,difficulty:"hard",question:n("Artalde baten % 70 ardiak dira eta gainerakoak ahuntzak. 60 ahuntz badaude, zenbat buru ditu artaldeak?","El 70 % de un rebaño son ovejas y el resto cabras. Si hay 60 cabras, ¿cuántas cabezas tiene el rebaño?","70٪ من قطيع نعاج والباقي ماعز. إذا كان الماعز 60، فكم رأسًا في القطيع؟","70% of a flock are sheep and the rest are goats. If there are 60 goats, how many animals are in the flock?"),solution:c("$100-70=30\\ \\to\\ 60\\mathbin{:}30\\cdot 100=200$"),answer:{expected:h(200)}}]},{id:"changes",title:n("Igoerak, beherapenak eta problemak","Aumentos, descuentos y problemas","الزيادات والتخفيضات والمسائل","Increases, discounts and problems"),items:[{id:41,difficulty:"easy",question:n("% 10eko beherapena: zer ehuneko ordaintzen da? Eta % 25ekoarekin?","Con un descuento del 10 %, ¿qué porcentaje se paga? ¿Y con uno del 25 %?","مع خصم 10٪، ما النسبة التي تُدفع؟ ومع خصم 25٪؟","With a 10% discount, what percentage do you pay? And with a 25% discount?"),solution:n("% 90 eta % 75.","El 90 % y el 75 %.","90٪ و75٪.","90% and 75%.")},{id:42,difficulty:"easy",question:n("Bizikleta batek 200 € balio zuen eta % 5 garestitu da. Zenbat balio du orain?","Una bici costaba 200 € y ha subido un 5 %. ¿Cuánto cuesta ahora?","كان ثمن دراجة 200 € وارتفع 5٪. كم ثمنها الآن؟","A bike cost €200 and its price has gone up by 5%. How much does it cost now?"),solution:c("$200\\cdot 5\\mathbin{:}100=10\\ \\to\\ 200+10=210$"),answer:{expected:h(210)}},{id:43,difficulty:"easy",question:n("Beroki batek 80 € balio du eta % 10 merkatu dute. Zenbat ordainduko dut?","Un abrigo cuesta 80 € y lo rebajan un 10 %. ¿Cuánto pagaré?","ثمن معطف 80 € وخُفّض 10٪. كم سأدفع؟","A coat costs €80 and is reduced by 10%. How much will I pay?"),solution:c("$80\\cdot 10\\mathbin{:}100=8\\ \\to\\ 80-8=72$"),answer:{expected:h(72)}},{id:44,difficulty:"medium",question:n("Zapatilek 60 € balio dute eta % 15eko beherapena dute. Kalkulatu prezioa bider $0{,}85$ eginez.","Unas zapatillas de 60 € tienen un 15 % de descuento. Calcula el precio multiplicando por $0{,}85$.","حذاء رياضي ثمنه 60 € بخصم 15٪. احسب السعر بالضرب في $0{,}85$.","A pair of trainers costing €60 has a 15% discount. Work out the price by multiplying by $0{,}85$."),solution:c("$60\\cdot 0{,}85=51$"),answer:{expected:h(51)}},{id:45,difficulty:"medium",question:n("Telefono batek 150 € balio zuen eta % 20 garestitu da. Zenbat balio du orain?","Un teléfono costaba 150 € y ha subido un 20 %. ¿Cuánto cuesta ahora?","كان ثمن هاتف 150 € وارتفع 20٪. كم ثمنه الآن؟","A phone cost €150 and its price has gone up by 20%. How much does it cost now?"),solution:c("$150\\cdot 1{,}2=180$"),answer:{expected:h(180)}},{id:46,difficulty:"medium",question:n("Zein metodo? a) 3 kg-k 6 € balio badute, 5 kg; b) 4 langilek 6 egun badira, 8 langile; c) 60ren % 15.","¿Qué método? a) Si 3 kg cuestan 6 €, 5 kg; b) si 4 obreros tardan 6 días, 8 obreros; c) el 15 % de 60.","أي طريقة؟ أ) إذا كان ثمن 3 كغ 6 €، فكم ثمن 5 كغ؛ ب) إذا احتاج 4 عمال 6 أيام، فكم يحتاج 8 عمال؛ ج) 15٪ من 60.","Which method? a) If 3 kg cost €6, how much do 5 kg cost? b) If 4 workers take 6 days, how long do 8 workers take? c) 15% of 60."),solution:n("a) zuzena: $6\\mathbin{:}3\\cdot 5=10$; b) alderantzizkoa: $4\\cdot 6\\mathbin{:}8=3$; c) ehunekoa: $60\\cdot 15\\mathbin{:}100=9$.","a) directa: $6\\mathbin{:}3\\cdot 5=10$; b) inversa: $4\\cdot 6\\mathbin{:}8=3$; c) porcentaje: $60\\cdot 15\\mathbin{:}100=9$.","أ) طردي: $6\\mathbin{:}3\\cdot 5=10$؛ ب) عكسي: $4\\cdot 6\\mathbin{:}8=3$؛ ج) نسبة: $60\\cdot 15\\mathbin{:}100=9$.","a) direct: $6\\mathbin{:}3\\cdot 5=10$; b) inverse: $4\\cdot 6\\mathbin{:}8=3$; c) percentage: $60\\cdot 15\\mathbin{:}100=9$.")},{id:47,difficulty:"medium",question:n("Kontzertu baterako 1200 sarreratik % 85 saldu dira. Zenbat sarrera geratzen dira?","De 1200 entradas para un concierto se ha vendido el 85 %. ¿Cuántas entradas quedan?","بيع 85٪ من 1200 تذكرة لحفل. كم تذكرة بقيت؟","Of 1,200 tickets for a concert, 85% have been sold. How many tickets are left?"),solution:c("$100-85=15\\ \\to\\ 1200\\cdot 15\\mathbin{:}100=180$"),answer:{expected:h(180)}},{id:48,difficulty:"hard",question:n("Kamiseta batek 24 € balio du beherapena egin ondoren; % 20 merkatu dute. Zenbat balio zuen lehen?","Una camiseta cuesta 24 € después de rebajarla un 20 %. ¿Cuánto costaba antes?","ثمن قميص 24 € بعد تخفيضه 20٪. كم كان ثمنه قبل ذلك؟","A T-shirt now costs €24 after a 20% discount. How much did it cost before?"),solution:c("$100-20=80\\ \\to\\ 24\\mathbin{:}80\\cdot 100=30$"),answer:{expected:h(30)}},{id:49,difficulty:"hard",question:n("Merluza-kilo eta laurden batek $15{,}75$ € balio du. Zenbat balio du $1{,}4$ kg-ko beste batek?","Una merluza de kilo y cuarto cuesta $15{,}75$ €. ¿Cuánto cuesta otra de $1{,}4$ kg?","ثمن سمكة نازلي وزنها كيلو وربع $15{,}75$ €. كم ثمن أخرى وزنها $1{,}4$ كغ؟","A hake weighing 1.25 kg costs €$15{,}75$. How much does another one weighing $1{,}4$ kg cost?"),solution:c("$15{,}75\\mathbin{:}1{,}25=12{,}6\\ \\to\\ 12{,}6\\cdot 1{,}4=17{,}64$"),answer:{expected:T("17,64")}},{id:50,difficulty:"hard",question:n("Isun bati % 15eko errekargua jarri diote eta guztira $86{,}25$ € ordaindu dira. Zenbatekoa zen isuna?","A una multa le han puesto un recargo del 15 % y se han pagado $86{,}25$ € en total. ¿De cuánto era la multa?","فُرض على مخالفة رسم إضافي 15٪ ودُفع في المجموع $86{,}25$ €. كم كانت قيمة المخالفة؟","A 15% surcharge was added to a fine, and €$86{,}25$ was paid in total. What was the original fine?"),solution:c("$100+15=115\\ \\to\\ 86{,}25\\mathbin{:}115\\cdot 100=75$"),answer:{expected:h(75)}}]}],ze=6,ga=["percent-forms","percent-of","proportion"],fa=[[50,"\\frac{1}{2}"],[25,"\\frac{1}{4}"],[75,"\\frac{3}{4}"],[10,"\\frac{1}{10}"],[20,"\\frac{1}{5}"],[40,"\\frac{2}{5}"],[5,"0{,}05"],[9,"0{,}09"],[85,"0{,}85"],[30,"0{,}3"],[60,"0{,}6"],[15,"0{,}15"],[1,"0{,}01"],[100,"1"]];function za(e){const[i,a]=x(e,fa);return{question:`${i}\\,\\%`,answer:a,key:i}}function xa(e){const i=x(e,[10,20,25,50,75,5,30]),a=k(e,1,12)*20,t=a*i/100;return{question:`${i}\\,\\%\\cdot ${a}`,answer:String(t).replace(".","{,}"),key:t}}fu